"""The API against its own OpenAPI document, with requests generated by schemathesis.

The run is bounded and reproducible: a fixed seed, a fixed number of examples
per operation, no example database and no shrinking, so the same twin gets the
same requests every time. A failing response is recorded and the run goes on,
so one report lists every failure. The token reaches schemathesis only as a
header of the requests it sends; failures are reported by method, path, query
and status, never with the headers.
"""

from __future__ import annotations

import time
from collections.abc import Callable
from typing import Any

import schemathesis
from dta_core.log import Log
from hypothesis import HealthCheck, Phase, given, seed, settings
from schemathesis.checks import (
    content_type_conformance,
    not_a_server_error,
    response_headers_conformance,
    response_schema_conformance,
    status_code_conformance,
)
from schemathesis.core.failures import Failure, FailureGroup

from .client import TwinApi
from .readiness import API
from .result import CheckResult, problem_of

log = Log("acceptance.contract")

DEFAULT_EXAMPLES = 20
DEFAULT_SEED = 20_261_111
CHECKS = [
    not_a_server_error,
    status_code_conformance,
    content_type_conformance,
    response_schema_conformance,
    response_headers_conformance,
]
_MESSAGE_MAX = 600
_REPORTED_FAILURES = 50


def _request_of(case: schemathesis.Case) -> dict[str, Any]:
    return {
        "method": case.method.upper(),
        "path": case.formatted_path,
        "query": dict(case.query or {}),
        "body": case.body if isinstance(case.body, dict | list) else None,
    }


def _failure(operation: str, case: schemathesis.Case, status: int | None, failure: Failure) -> dict:
    return {
        "operation": operation,
        "request": _request_of(case),
        "status": status,
        "check": failure.code,
        "title": failure.title,
        "message": (failure.message or "")[:_MESSAGE_MAX],
    }


def _exerciser(
    base_url: str,
    auth: dict[str, str],
    label: str,
    sent: dict[str, int],
    failures: list[dict[str, Any]],
) -> Callable[[schemathesis.Case], None]:
    """One operation's test body; hypothesis refuses to wrap a function with defaults."""

    def exercise(case: schemathesis.Case) -> None:
        sent["requests"] += 1
        reply = case.call(base_url=base_url, headers=auth, timeout=60)
        try:
            case.validate_response(reply, checks=CHECKS, headers=auth)
        except FailureGroup as group:
            sent["failures"] += len(group.exceptions)
            for failure in group.exceptions:
                failures.append(_failure(label, case, reply.status_code, failure))
        except Failure as failure:
            sent["failures"] += 1
            failures.append(_failure(label, case, reply.status_code, failure))

    return exercise


def api_contract(
    api: TwinApi, examples: int = DEFAULT_EXAMPLES, run_seed: int = DEFAULT_SEED
) -> CheckResult:
    examined = (
        f"schemathesis against /api/v1/openapi.json: {examples} generated requests per operation, "
        f"seed {run_seed}; no 5xx, status codes, content types, headers and bodies as declared"
    )
    remedy = (
        "Fix the API so that it answers as its OpenAPI document says (see the failing requests)."
    )
    response = api.get(f"{API}/openapi.json")
    if response.status_code != 200:
        return CheckResult(
            id="api.contract",
            examined=examined,
            passed=False,
            evidence={
                "failing_request": f"GET {API}/openapi.json",
                "response": problem_of(response),
            },
            remedy=remedy,
        )
    schema = schemathesis.openapi.from_dict(
        response.json(), config=schemathesis.Config(seed=run_seed)
    )
    auth = {"Authorization": f"Bearer {api.token}"}
    failures: list[dict[str, Any]] = []
    operations: list[dict[str, Any]] = []
    errors: list[dict[str, Any]] = []
    for result in schema.get_all_operations():
        operation = result.ok()
        label = f"{operation.method.upper()} {operation.path}"
        sent = {"requests": 0, "failures": 0}
        started = time.perf_counter()

        exercise = _exerciser(api.base_url, auth, label, sent, failures)
        test = settings(
            max_examples=examples,
            deadline=None,
            database=None,
            phases=[Phase.generate],
            suppress_health_check=list(HealthCheck),
            print_blob=False,
        )(seed(run_seed)(given(case=operation.as_strategy())(exercise)))
        try:
            test()
        except Exception as exc:  # noqa: BLE001 - one operation that cannot run must not end the check
            log.error("operation could not be exercised", exc=exc, operation=label)
            errors.append(
                {"operation": label, "error": f"{type(exc).__name__}: {str(exc)[:_MESSAGE_MAX]}"}
            )
        operations.append({"operation": label, **sent})
        log.debug(
            "operation exercised",
            operation=label,
            requests=sent["requests"],
            failures=sent["failures"],
            duration_ms=round((time.perf_counter() - started) * 1000.0, 1),
        )
    passed = not failures and not errors and bool(operations)
    evidence = {
        "seed": run_seed,
        "examples_per_operation": examples,
        "operations": len(operations),
        "requests": sum(entry["requests"] for entry in operations),
        "failures": len(failures),
        "failing": failures[:_REPORTED_FAILURES],
        "errors": errors,
        "per_operation": operations,
    }
    if not passed:
        log.warn("API contract check failed", failures=len(failures), errors=len(errors))
    return CheckResult(
        id="api.contract", examined=examined, passed=passed, evidence=evidence, remedy=remedy
    )
